#include <cmath>
#include <sstream>

static std::string text(const Fraction& f) {
  std::ostringstream o;
  o << f;
  return o.str();
}

TEST("stored in lowest terms with a positive denominator") {
  Fraction a(2, 4), b(3, -6), c(0, 5), d(-4, -8);
  CHECK_EQ(a.numerator(), 1L);  CHECK_EQ(a.denominator(), 2L);
  CHECK_EQ(b.numerator(), -1L); CHECK_EQ(b.denominator(), 2L);
  CHECK_EQ(c.numerator(), 0L);  CHECK_EQ(c.denominator(), 1L);
  CHECK_EQ(d.numerator(), 1L);  CHECK_EQ(d.denominator(), 2L);
}

TEST("a zero denominator throws invalid_argument") {
  CHECK_THROWS(Fraction(1, 0), std::invalid_argument);
}

TEST("arithmetic between fractions") {
  CHECK(Fraction(1, 2) + Fraction(1, 3) == Fraction(5, 6));
  CHECK(Fraction(1, 2) - Fraction(3, 4) == Fraction(-1, 4));
  CHECK(Fraction(2, 3) * Fraction(9, 4) == Fraction(3, 2));
  CHECK(Fraction(1, 2) / Fraction(1, 4) == Fraction(2));
}

TEST("integers work on either side") {
  CHECK(Fraction(1, 2) + 1 == Fraction(3, 2));
  CHECK(1 + Fraction(1, 2) == Fraction(3, 2));
  CHECK(2 * Fraction(3, 4) == Fraction(3, 2));
}

TEST("dividing by zero throws") {
  CHECK_THROWS(Fraction(1, 2) / Fraction(0), std::invalid_argument);
}

TEST("comparison") {
  CHECK(Fraction(1, 3) < Fraction(1, 2));
  CHECK(Fraction(-1, 2) < Fraction(1, 3));
  CHECK(!(Fraction(1, 2) < Fraction(2, 4)));
  CHECK(Fraction(2, 4) == Fraction(1, 2));
}

TEST("printing") {
  CHECK_EQ(text(Fraction(3, 4)), std::string("3/4"));
  CHECK_EQ(text(Fraction(4, 2)), std::string("2"));
  CHECK_EQ(text(Fraction(1, -3)), std::string("-1/3"));
}

TEST("to_double") {
  CHECK(std::abs(Fraction(1, 4).to_double() - 0.25) < 1e-12);
}

