#include <compare>
#include <numeric>
#include <ostream>
#include <stdexcept>

class Fraction {
 public:
  // Not `explicit`: lets an int convert to a Fraction, so `1 + f` works.
  Fraction(long num, long den = 1) : num_(num), den_(den) {
    if (den_ == 0) throw std::invalid_argument("denominator is zero");
    if (den_ < 0) {
      num_ = -num_;
      den_ = -den_;
    }
    long g = std::gcd(num_, den_);  // gcd(0, d) == d, so 0/d becomes 0/1
    num_ /= g;
    den_ /= g;
  }

  long numerator() const { return num_; }
  long denominator() const { return den_; }
  double to_double() const { return static_cast<double>(num_) / den_; }

  // Non-member ("hidden friend") operators: both operands get the same implicit
  // conversions, so 1 + f works as well as f + 1. A member operator+ would only
  // convert the right-hand side.
  friend Fraction operator+(const Fraction& a, const Fraction& b) {
    return {a.num_ * b.den_ + b.num_ * a.den_, a.den_ * b.den_};
  }
  friend Fraction operator-(const Fraction& a, const Fraction& b) {
    return {a.num_ * b.den_ - b.num_ * a.den_, a.den_ * b.den_};
  }
  friend Fraction operator*(const Fraction& a, const Fraction& b) { return {a.num_ * b.num_, a.den_ * b.den_}; }
  friend Fraction operator/(const Fraction& a, const Fraction& b) { return {a.num_ * b.den_, a.den_ * b.num_}; }

  // Normalised storage makes member-wise equality correct.
  friend bool operator==(const Fraction&, const Fraction&) = default;
  friend std::strong_ordering operator<=>(const Fraction& a, const Fraction& b) {
    return a.num_ * b.den_ <=> b.num_ * a.den_;  // denominators are positive, so no sign flip
  }

  friend std::ostream& operator<<(std::ostream& os, const Fraction& f) {
    os << f.num_;
    if (f.den_ != 1) os << '/' << f.den_;
    return os;
  }

 private:
  long num_, den_;
};
